package com.adc.infrastructure;

import static org.junit.jupiter.api.Assertions.*;
import com.adc.application.*;
import com.adc.application.performance.PerformancePublicationService;
import com.adc.domain.shared.DomainFailure;
import com.adc.identity.IdentityGate;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;

/** Independent application contexts, pools and transaction managers share only real MySQL. */
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ConcurrencyFailureIT {
    final QuarterlyPerformanceIT fixture=new QuarterlyPerformanceIT();AnnotationConfigApplicationContext second;PerformancePublicationService remote;
    @BeforeAll void migrate()throws Exception{fixture.migrate();}
    @AfterAll void dispose(){fixture.dispose();}
    StaffAccountsIT base(){return fixture.base();}
    @BeforeEach void setup()throws Exception{fixture.setup();fixture.ready();base().db.update("INSERT INTO adc_identity.AccessGrant VALUES ('second-app-review','other','HEADQUARTERS','hq',?,NULL,NULL,NULL,'owned independent instance',?)",StaffAccountsIT.utc(base().now),StaffAccountsIT.utc(base().now));for(long clinic:List.of(1L,2L))base().db.update("INSERT INTO adc_identity.GrantClinicScope VALUES ('second-app-review',?)",clinic);base().db.update("INSERT INTO adc_identity.GrantCapability VALUES ('second-app-review','performance.publish')");second=new AnnotationConfigApplicationContext();second.register(StaffAccountsIT.Transactions.class);second.registerBean(com.zaxxer.hikari.HikariDataSource.class,()->base().runtimeDataSource());second.registerBean(JdbcTemplate.class,()->new JdbcTemplate(second.getBean(com.zaxxer.hikari.HikariDataSource.class)));second.registerBean(DataSourceTransactionManager.class,()->new DataSourceTransactionManager(second.getBean(com.zaxxer.hikari.HikariDataSource.class)));second.registerBean(Clock.class,()->Clock.fixed(base().now,ZoneOffset.UTC));second.registerBean(TransactionLocks.class,()->new TransactionLocks(second.getBean(com.zaxxer.hikari.HikariDataSource.class)));second.register(IdentityGate.class,AuditWriter.class,RequestReceiptStore.class,AtomicCommandExecutor.class,BusinessRowLocks.class,QuarterlyPerformanceStore.class,PerformancePublicationService.class);second.refresh();remote=second.getBean(PerformancePublicationService.class);assertNotEquals(base().db.queryForObject("SELECT CONNECTION_ID()",Long.class),second.getBean(JdbcTemplate.class).queryForObject("SELECT CONNECTION_ID()",Long.class));}
    @AfterEach void close(){if(second!=null)second.close();fixture.close();}
    Map<String,Object> calculate(String suffix)throws Exception{var p=fixture.preparation();var response=fixture.performance.prepare(fixture.command("prepareQuarterPerformance","preparation-"+suffix),p);var ids=((List<?>)response.get("items")).stream().map(r->(String)((Map<?,?>)r).get("quarterly_performance_id")).toList();return fixture.dentist(fixture.calculate("calculation-"+suffix,ids),22);}
    AtomicCommandExecutor.Command remoteCommand(String key){return new AtomicCommandExecutor.Command(base().other,"WEB","publishQuarterPerformance",key,Crypto.sha256(key),UUID.randomUUID().toString());}
    Map<String,Object> publish(PerformancePublicationService service,AtomicCommandExecutor.Command command,Map<String,Object> row)throws Exception{return service.publish(command,Long.parseLong((String)row.get("quarterly_performance_id")),new PerformancePublicationService.Publish((String)row.get("input_hash"),"verified source reconciliation on an independent request"));}
    @Test void initialAndReplacementPublishingAcrossInstancesNeverRegressesCurrentVersion()throws Exception{var original=calculate("original");try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var a=pool.submit(()->{start.await();return publish(fixture.publications,fixture.review("initial-a"),original);});var b=pool.submit(()->{start.await();return publish(remote,remoteCommand("initial-b"),original);});start.countDown();assertEquals("PUBLISHED",a.get(20,TimeUnit.SECONDS).get("calculation_status"));assertEquals("PUBLISHED",b.get(20,TimeUnit.SECONDS).get("calculation_status"));}fixture.cost(1,22L,"OPERATING","10.00","replacement-two");var middle=calculate("middle");fixture.cost(1,22L,"OPERATING","20.00","replacement-three");var newest=calculate("newest");try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var a=pool.submit(()->{start.await();try{publish(fixture.publications,fixture.review("replace-middle"),middle);return 200;}catch(DomainFailure denied){return denied.status();}});var b=pool.submit(()->{start.await();publish(remote,remoteCommand("replace-newest"),newest);return 200;});start.countDown();assertTrue(Set.of(200,409).contains(a.get(20,TimeUnit.SECONDS)));assertEquals(200,b.get(20,TimeUnit.SECONDS));}assertEquals(1,base().db.queryForObject("SELECT COUNT(*) FROM adc_business.QuarterlyPerformance WHERE dentist_id=22 AND calculation_status='PUBLISHED'",Integer.class));assertEquals(newest.get("quarterly_performance_id"),base().db.queryForObject("SELECT quarterly_performance_id FROM adc_business.QuarterlyPerformance WHERE dentist_id=22 AND calculation_status='PUBLISHED'",Long.class).toString());assertEquals("SUPERSEDED",base().db.queryForObject("SELECT calculation_status FROM adc_business.QuarterlyPerformance WHERE quarterly_performance_id=?",String.class,Long.parseLong((String)original.get("quarterly_performance_id"))));}
    @Test void remoteAuditFailureRollsBackBothSidesOfReplacementAndOriginalKeyRemainsRetryable()throws Exception{var original=calculate("original");publish(fixture.publications,fixture.review("publish-original"),original);fixture.cost(1,22L,"OPERATING","10.00","replacement-cost");var next=calculate("replacement");var command=remoteCommand("remote-failure-original-key");try(var c=base().connection("inspector");var sql=c.createStatement()){sql.execute("REVOKE INSERT ON adc_audit.* FROM 'adc_runtime_role'");try{assertThrows(org.springframework.dao.DataAccessException.class,()->publish(remote,command,next));}finally{sql.execute("GRANT INSERT ON adc_audit.* TO 'adc_runtime_role'");}}assertEquals(original.get("quarterly_performance_id"),base().db.queryForObject("SELECT quarterly_performance_id FROM adc_business.QuarterlyPerformance WHERE dentist_id=22 AND calculation_status='PUBLISHED'",Long.class).toString());assertEquals(0,base().db.queryForObject("SELECT COUNT(*) FROM adc_identity.RequestReceipt WHERE request_key='remote-failure-original-key'",Integer.class));assertEquals("PUBLISHED",publish(remote,command,next).get("calculation_status"));}
}
